CREATE FUNCTION photo.account_legal_set_hash(p_doc_ids uuid[]) RETURNS bytea
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE
 v_concat bytea:=''::bytea; v_rec record;
BEGIN
 FOR v_rec IN
  SELECT content_sha256 FROM photo.legal_document_versions
  WHERE document_id=ANY(p_doc_ids) ORDER BY document_id
