CREATE FUNCTION photo.account_accept_legal(
 p_tenant uuid,p_actor uuid,p_session uuid,
 p_document_versions jsonb,
 p_explicit_actions jsonb,
 p_client_event text
) RETURNS TABLE(state text,revision bigint,accepted_set_hash bytea)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE
 v_locale text; v_doc_ids uuid[]; v_req_ids uuid[];
 v_accepted bytea; v_required bytea; v_row photo.account_onboarding_states%ROWTYPE;
 v_ev jsonb; v_doc photo.legal_document_versions%ROWTYPE;
BEGIN
 IF nullif(current_setting('app.tenant_id',true),'')::uuid IS DISTINCT FROM p_tenant
 THEN RAISE EXCEPTION 'BILLING_AUTHORITY_INVALID'; END IF;
 IF NOT EXISTS(SELECT 1 FROM photo.authorize_tenant(p_actor,p_session,p_tenant))
 THEN RAISE EXCEPTION 'BILLING_AUTHORITY_INVALID'; END IF;
 IF NOT COALESCE((p_explicit_actions->>'contract_accepted')::boolean,false)
 THEN RAISE EXCEPTION 'LEGAL_CONTRACT_NOT_ACCEPTED'; END IF;
 IF NOT COALESCE((p_explicit_actions->>'privacy_acknowledged')::boolean,false)
 THEN RAISE EXCEPTION 'LEGAL_PRIVACY_NOT_ACKNOWLEDGED'; END IF;
 FOR v_ev IN SELECT value FROM jsonb_array_elements(p_document_versions->'events') LOOP
  IF (v_ev->>'action') NOT IN ('accepted','acknowledged')
  THEN RAISE EXCEPTION 'LEGAL_INVALID_ACTION'; END IF;
  SELECT * INTO v_doc FROM photo.legal_document_versions
  WHERE document_id=(v_ev->>'version_id')::uuid AND state='active';
  IF NOT FOUND THEN RAISE EXCEPTION 'LEGAL_DOCUMENT_NOT_ACTIVE'; END IF;
  IF v_doc.document_key IN ('terms','dpa','photoeditor_addendum') AND v_ev->>'action'!='accepted'
  THEN RAISE EXCEPTION 'LEGAL_ACTION_MISMATCH'; END IF;
  IF v_doc.document_key IN ('privacy','cookies') AND v_ev->>'action'!='acknowledged'
  THEN RAISE EXCEPTION 'LEGAL_ACTION_MISMATCH'; END IF;
  IF v_locale IS NULL THEN v_locale:=v_doc.locale;
  ELSIF v_locale!=v_doc.locale THEN RAISE EXCEPTION 'LEGAL_LOCALE_MISMATCH'; END IF;
  v_doc_ids:=array_append(v_doc_ids,v_doc.document_id);
 END LOOP;
 IF coalesce(array_length(v_doc_ids,1),0)=0 THEN RAISE EXCEPTION 'LEGAL_NO_EVENTS'; END IF;
 v_accepted:=photo.account_legal_set_hash(v_doc_ids);
 SELECT array_agg(document_id) INTO v_req_ids FROM photo.legal_document_versions
 WHERE locale=v_locale AND state='active';
 IF coalesce(array_length(v_req_ids,1),0)=0 THEN RAISE EXCEPTION 'LEGAL_NO_ACTIVE_DOCUMENTS'; END IF;
 v_required:=photo.account_legal_set_hash(v_req_ids);
 IF v_accepted!=v_required THEN RAISE EXCEPTION 'LEGAL_REQUIRED_SET_MISMATCH'; END IF;
 SELECT * INTO v_row FROM photo.account_onboarding_states WHERE user_id=p_actor FOR UPDATE;
 IF FOUND AND v_row.state='complete' THEN
  IF v_row.accepted_document_set_hash=v_accepted THEN
   RETURN QUERY SELECT v_row.state,v_row.revision,v_row.accepted_document_set_hash; RETURN;
  END IF;
  RAISE EXCEPTION 'LEGAL_ACCEPTANCE_HASH_CONFLICT';
 END IF;
 IF NOT FOUND THEN
  INSERT INTO photo.account_onboarding_states(user_id,state,required_document_set_hash)
  VALUES(p_actor,'pending',v_required) ON CONFLICT(user_id) DO NOTHING;
  SELECT * INTO v_row FROM photo.account_onboarding_states WHERE user_id=p_actor FOR UPDATE;
 END IF;
 UPDATE photo.account_onboarding_states
 SET state='complete',accepted_document_set_hash=v_accepted,required_document_set_hash=v_required,
     revision=revision+1,completed_at=clock_timestamp(),updated_at=clock_timestamp()
 WHERE user_id=p_actor RETURNING * INTO v_row;
 RETURN QUERY SELECT v_row.state,v_row.revision,v_row.accepted_document_set_hash;
END $$;
